    "A milésima porta cedeu. Por enquanto, o castelo ficou em silêncio.": "천 개의 문이 길을 열었다. 지금까지 성은 침묵했다.",
    "A partir da fase 5 o castelo abandona qualquer respeito pelo jogador. Terra, Ar, Luz e Escuridão têm movimentos, imunidades e habilidades próprias. As armadilhas continuam determinísticas: morrer ensina alguma coisa — mesmo quando dá vontade de fechar o jogo.": "레벨 5에서 앞으로, 성은 플레이어에 대한 모든 존경을 포기합니다. 지구, 공기, 빛, 어둠은 자신의 움직임, 면역력 및 능력을 가지고 있습니다. 계단은 결정적으로 남아있다 : 죽는 것은 당신에게 무언가를 가르칩니다 - 심지어 당신이 게임을 닫는 것처럼 느낄 때조차.",
