    "A partir da fase 5 o castelo abandona qualquer respeito pelo jogador. Terra, Ar, Luz e Escuridão têm movimentos, imunidades e habilidades próprias. As armadilhas continuam determinísticas: morrer ensina alguma coisa — mesmo quando dá vontade de fechar o jogo.": "5. seviyeden itibaren kale oyuncuya olan tüm saygısını kaybeder. Toprak, Hava, Işık ve Karanlığın kendi hareketleri, bağışıklıkları ve yetenekleri vardır. Tuzaklar belirleyici olmaya devam ediyor: Ölmek size bir şeyler öğretir; oyunu kapatmak isteseniz bile.",
    "A partir daqui o castelo deixa de fingir que é seu amigo.": "Şu andan itibaren kale arkadaşınmış gibi davranmayı bırakacak.",
