    "A campanha começa quando os quatro elementos estiverem na sala e todos estiverem prontos.": "競選活動開始時,所有四個元素都在房間裡,每個人都準備好了。",
    "A fase começa quando os dois estiverem prontos.": "比賽開始時,兩名球員都準備好了。",
    "A milésima porta cedeu. Por enquanto, o castelo ficou em silêncio.": "千之門走路了。 到目前為止,城堡沉默了。",
    "A partir da fase 5 o castelo abandona qualquer respeito pelo jogador. Terra, Ar, Luz e Escuridão têm movimentos, imunidades e habilidades próprias. As armadilhas continuam determinísticas: morrer ensina alguma coisa — mesmo quando dá vontade de fechar o jogo.": "從5級到5級,城堡放棄對球員的所有尊重。 地球、空氣、光和黑暗有自己的運動、免疫力和能力。 陷阱仍然是決定性的:死亡教你一些東西 - 即使你覺得關閉遊戲。",
    "A partir daqui o castelo deixa de fingir que é seu amigo.": "從這裡開始,城堡停止假裝是你的朋友。",
    "A porta abriu. O castelo também. Alguma coisa saiu com você.": "門開啟了。 城堡就是這樣。 有些東西留在你身邊。",
    "A relíquia recusou esta morte.": "古老的藝術品拒絕了這個死亡。",
