    ". Portas e chefes se adaptam para continuarem possíveis com um único personagem.": "。ドアとボスは、単一のキャラクターでも可能なままになるように適応します。",
    "4 elementos únicos": "4 つのユニークな要素",
    "4 jogadores obrigatórios": "プレイヤーは 4 人必要です",
    "4 jogadores · 4 elementos · uma campanha sem misericórdia.": "4 人のプレイヤー、4 つの要素、1 つの容赦ないキャンペーン。",
    "A Bibliotecária Morta": "死んだ司書",
    "A SALA QUE NÃO DEVIA EXISTIR": "存在してはいけない部屋",
    "A campanha começa quando os quatro elementos estiverem na sala e todos estiverem prontos.": "キャンペーンは、4 つの要素すべてが部屋にあり、全員の準備ができたときに始まります。",
    "A fase começa quando os dois estiverem prontos.": "両方のプレイヤーが準備ができたときにレベルが開始されます。",
    "A milésima porta cedeu. Por enquanto, o castelo ficou em silêncio.": "千番目のドアが道を譲りました。とりあえず城は静まり返った。",
    "A partir da fase 5 o castelo abandona qualquer respeito pelo jogador. Terra, Ar, Luz e Escuridão têm movimentos, imunidades e habilidades próprias. As armadilhas continuam determinísticas: morrer ensina alguma coisa — mesmo quando dá vontade de fechar o jogo.": "レベル 5 以降、城はプレイヤーに対する一切の敬意を放棄します。地球、空気、光、闇にはそれぞれ独自の動き、免疫力、能力があります。トラップは決定的なものです。ゲームを閉じたいと思ったときでも、死は何かを教えてくれます。",
    "A partir daqui o castelo deixa de fingir que é seu amigo.": "ここから、城はあなたの友人のふりをするのをやめます。",
    "A porta abriu. O castelo também. Alguma coisa saiu com você.": "ドアが開きました。城もそうでした。あなたに何かが残されました。",
    "A relíquia recusou esta morte.": "遺物はこの死を拒否した。",
    "A sala 666 não registra mortes. Ela registra visitantes.": "666号室では死亡は記録されていない。訪問者を記録します。",
    "A sala {0} não consta nos mapas do castelo. Alguém a construiu depois.": "部屋 {0} は城の地図にありません。後から誰かが建てたんだ。",
    "A saída do Caos foi liberada. Agora os quatro precisam alcançá-la.": "カオス出口のロックが解除されました。今度は 4 人のプレイヤー全員が到達する必要があります。",
    "A saída parecia perto demais, né?": "出口が近すぎますね。",
    "A saída viu você chegando e mudou de ideia.": "出口はあなたが来るのを見て考えを変えました。",
    "A versão web atualiza pelo service worker. Quando houver versão nova, basta recarregar.": "Web バージョンは Service Worker を通じて更新されます。新しいバージョンが利用可能になったらリロードします。",
    "A versão {0} está esperando por você.": "バージョン {0} があなたを待っています。",
