    "A campanha começa quando os quatro elementos estiverem na sala e todos estiverem prontos.": "竞选活动开始时,所有四个元素都在房间里,每个人都准备好了。",
    "A fase começa quando os dois estiverem prontos.": "比赛开始时,两名球员都准备好了。",
    "A milésima porta cedeu. Por enquanto, o castelo ficou em silêncio.": "千之门走路了。 到目前为止,城堡沉默了。",
    "A partir da fase 5 o castelo abandona qualquer respeito pelo jogador. Terra, Ar, Luz e Escuridão têm movimentos, imunidades e habilidades próprias. As armadilhas continuam determinísticas: morrer ensina alguma coisa — mesmo quando dá vontade de fechar o jogo.": "从5级到5级,城堡放弃对球员的所有尊重。 地球、空气、光和黑暗有自己的运动、免疫力和能力。 陷阱仍然是决定性的:死亡教你一些东西 - 即使你觉得关闭游戏。",
    "A partir daqui o castelo deixa de fingir que é seu amigo.": "从这里开始,城堡停止假装是你的朋友。",
    "A porta abriu. O castelo também. Alguma coisa saiu com você.": "门打开了。 城堡就是这样。 有些东西留在你身边。",
    "A relíquia recusou esta morte.": "古老的艺术品拒绝了这个死亡。",
